class AutoFallbackNode(NetactNode):

    def __init__(self, node_mrbts_id: str, source_sw: str, target_sw: str,
                 node_alias: Optional[str] = None, node_vm: Union[str, dict] = None,
                 secondary_vm: Union[str, dict] = None, bts_host_ip: Optional[str] = "192.168.255.129",
                 external_dcap_host: Optional[str] = None, dcap_port: Optional[str] = "9443",
                 dcap_custom_profiles: Optional[dict] = None, hw_to_onair_timeout: Optional[int] = 900,
                 alarm_timer: Optional[int] = 60, custom_allowed_alarms: Optional[list] = None,
                 temporary_allowed_alarms: Optional[list] = None, critical_alarms: List[Union[str, Alarm]] = None,
                 pdu_config: Optional[list] = None,
                 logs_dir: Optional[str] = None, testline_scout_name: Optional[str] = None,
                 use_dcap: Optional[bool] = False, verify_syslog: Optional[bool] = True,
                 webem_username: str = 'Nemuadmin', webem_password: str = 'nemuuser',
                 node_ssh_username: str = "toor4nsn", node_ssh_password: str = "oZPS0POrRieRtu",
                 check_mplane: bool = True, setup_energy_saving: bool = False,
                 ru_manager_yaml_file: Union[str, None] = None, **kwargs):
        super().__init__(node_mrbts_id=node_mrbts_id, source_sw=source_sw, target_sw=target_sw, node_alias=node_alias,
                         node_vm=node_vm, secondary_vm=secondary_vm, bts_host_ip=bts_host_ip,
                         external_dcap_host=external_dcap_host, dcap_port=dcap_port,
                         dcap_custom_profiles=dcap_custom_profiles, hw_to_onair_timeout=hw_to_onair_timeout,
                         alarm_timer=alarm_timer, custom_allowed_alarms=custom_allowed_alarms,
                         temporary_allowed_alarms=temporary_allowed_alarms, critical_alarms=critical_alarms,
                         pdu_config=pdu_config, logs_dir=logs_dir, testline_scout_name=testline_scout_name,
                         use_dcap=use_dcap, verify_syslog=verify_syslog, webem_username=webem_username,
                         webem_password=webem_password, node_ssh_username=node_ssh_username,
                         node_ssh_password=node_ssh_password, check_mplane=check_mplane,
                         setup_energy_saving=setup_energy_saving, ru_manager_yaml_file=ru_manager_yaml_file, **kwargs)
        self.sw_fallback_timer = None
        self.trs_sfp = None
        self.fsm3 = True if self.ssh_manager.get_module_type() in ["FSMF", "FSIH"] else False

    @method_decorator("node_alias")
    def get_active_sfp(self):
        command = f'find /sys/class/sfp/sfp_0_*/tx_disable | xargs grep 0 2>&1'
        test_logger(f"checking active SFPs", console=False)
        try:
            output = self.ssh_manager.execute_command(command)
            return [sfp.split('/')[4] for sfp in output.split() if '/' in sfp]
        except Exception as e:
            test_logger(f"check_active_sfp, unexpected error occurred: {e}", "ERROR")

    @method_decorator("node_alias")
    def find_trs_sfp(self):
        active_sfp = self.get_active_sfp()
        test_logger(f"Looking for the TRS SFP: {active_sfp}", console=False)
        try:
            logging.getLogger("taf.sbts.oam.coam.admin").disabled = True
            for sfp in active_sfp:
                self.ssh_manager.execute_command(f"echo 1 > /sys/class/sfp/{sfp}/tx_disable")
                for _ in range(36):
                    time.sleep(5)
                    if self.verify_if_fault_exists(["61029", "6202", "7304", "2412", "2401"]):
                        test_logger(f"the {sfp} is the TRS FSP", console=False)
                        return sfp
                self.ssh_manager.execute_command(f"echo 0 > /sys/class/sfp/{sfp}/tx_disable")
            raise TrsFspError("Can't find the TRS SFP")
        except Exception as e:
            test_logger(f"Unexpected error occurred: {e}", "ERROR")
            raise
        finally:
            for sfp in active_sfp:
                self.ssh_manager.execute_command(f"echo 0 > /sys/class/sfp/{sfp}/tx_disable")
            logging.getLogger("taf.sbts.oam.coam.admin").disabled = False

    @method_decorator("node_alias")
    def toggle_port_443_access_on_smod(self, action: Literal['disable', 'enable']) -> None:
        """
            Toggles the access control of port 443 on the SMOD device based on the specified action.
            This method modifies the firewall rules to either block or unblock access to port 443
            from a specific IP address (192.168.255.126) on the SMOD device. The action to be performed
            is determined by the input parameter: 'enable' or 'disable'.
            Parameters:
            -----------
            action (str):
                The action to perform. Accepted values are:
                    - 'enable': Unblocks port 443 access.
                    - 'disable': Blocks port 443 access.
        """
        toggle = {"disable": "-I", "enable": "-D"}.get(action)
        line_nr = {"disable": " 1", "enable": ""}.get(action)
        if toggle is None:
            raise ToggleActionException(f"Invalid action: {action}. Use 'disable' or 'enable'")
        for _ in range(5):
            try:
                self.ssh_manager.execute_command(
                    f"iptables {toggle} INPUT{line_nr} -p tcp --dport 443 -s 192.168.255.126 -j REJECT")
                output = self.ssh_manager.execute_command("iptables -L INPUT")
                blocked = "192.168.255.126" in output
                if (blocked and action == "disable") or (not blocked and action == "enable"):
                    status = "successfully blocked" if action == "disable" else "successfully unblocked"
                    test_logger(f"Port 443 on the SMOD is {status}", console=False)
                    return
                time.sleep(1)
            except Exception as e:
                test_logger(f"toggle_port_443_access_on_smod exception: {e}", console=False)
        test_logger(f"Failed to block/unblock port 443 on the SMOD. Blocked: {blocked}, Action: {action}", "WARN")

    @method_decorator("node_alias")
    def sfp_tx_disable(self, sfp: str, index_range: Optional[int] = 20) -> None:
        """
            Disables the TX (transmit) signal for a specified SFP device.
            Parameters:
            -----------
            sfp : str
                The identifier of the SFP device (e.g., "sfp_0_0").
            index_range : Optional[int], default=20
                The range or index value associated with the TX disable operation.
                If not specified, defaults to 20.

            Returns:
            --------
            None
                This method does not return any value. It performs the TX disable action.
            """
        try:
            for _ in range(index_range):
                self.ssh_manager.execute_command(f"echo 1 > /sys/class/sfp/{sfp}/tx_disable")
                time.sleep(0.2)
            check = self.ssh_manager.execute_command(f"cat /sys/class/sfp/{sfp}/tx_disable")
            if int(check.split()[0]):
                test_logger(f"Tx successfully disabled on {sfp}", console=False)
        except Exception as e:
            test_logger(f"pingable: {self.is_smod_pingable()}", "DEBUG", console=False)
            test_logger(f"sfp_tx_disable exception: {e}", "DEBUG", console=False)

    @method_decorator("node_alias")
    def check_node_availability(self, timeout: Optional[int] = 600) -> bool:
        logging.getLogger("taf.transport.ssh").disabled = True
        try:
            with time_limit(timeout):
                while True:
                    if self.is_smod_pingable(ping_attempts=1):
                        return True
                    time.sleep(0.3)
        finally:
            logging.getLogger("taf.transport.ssh").disabled = False

    @method_decorator("node_alias")
    def disconnect_trs_and_wait_for_reset(self, reset_interval: int, test_stage=None,
                                          lower_threshold: float = 0.2, upper_threshold: float = 0.2,
                                          tx_disable: bool = True, time_without_reset = None) -> bool:
        start_time = max_reset_time = min_reset_time = None
        if self.check_node_availability():
            logging.getLogger("taf.transport.ssh").disabled = True
            logging.getLogger("taf.rfrl.csv4all.resources.node.ssh_manager.node_ssh_manager").disabled = True
            try:
                self.toggle_port_443_access_on_smod("disable")
                start_time = time.time()
                if tx_disable:
                    self.sfp_tx_disable(self.trs_sfp)
                lower_threshold_in_minutes = float(reset_interval) * lower_threshold
                upper_threshold_in_minutes = float(reset_interval) * upper_threshold
                max_reset_time = (float(reset_interval) + upper_threshold_in_minutes) * 60
                min_reset_time = (float(reset_interval) - lower_threshold_in_minutes) * 60
                msg = f" for {test_stage}" if test_stage else ""
                test_logger(f"Waiting {reset_interval} minutes{msg}")
                result = self.check_and_disable_tx(start_time, max_reset_time, tx_disable)
                if not result:
                    if test_stage in ["reset after fallback", "secondary reset after fallback"]:
                        return False
                    test_logger(
                        f"The timeout has been reached, and the BTS did not reset after {reset_interval}m",
                        "ERROR", hyperlink=True)
                    raise ResetTimingException
            finally:
                logging.getLogger("taf.transport.ssh").disabled = False
                logging.getLogger("taf.rfrl.csv4all.resources.node.ssh_manager.node_ssh_manager").disabled = False
        test_logger("The BTS reset has started")
        reset_time = time.time()
        reset_waiting_time = reset_time - start_time
        # if time_without_reset:
        #     time_without_reset += reset_waiting_time
        #     minutes, seconds = divmod(time_without_reset, 60)
        # else:
        #     minutes, seconds = divmod(reset_waiting_time, 60)
        waiting_time = reset_waiting_time if not time_without_reset else time_without_reset + reset_waiting_time
        minutes, seconds = divmod(waiting_time, 60)
        if test_stage:
            test_logger(f"{test_stage} notice after: {minutes:.0f}m {seconds:.0f}s")
        if min_reset_time <= reset_waiting_time <= max_reset_time:
            test_logger(f"The reset was completed within the expected timeframe")
            return True
        else:
            test_logger(f"The reset occurred much faster than {reset_interval} minutes", "ERROR", hyperlink=True)
            raise ResetTimingException

    @method_decorator("node_alias")
    def check_and_disable_tx(self, start_time, max_reset_time, tx_disable):
        while self.is_smod_pingable():
            check_point = time.time()
            if (check_point - start_time) <= max_reset_time:
                try:
                    if tx_disable:
                        if self.is_tx_enable():
                            self.sfp_tx_disable(self.trs_sfp)
                            test_logger(f"{self.trs_sfp} disabled", console=False)
                        time.sleep(1)
                    else:
                        time.sleep(30)
                except Exception as e:
                    smod_status = self.is_smod_pingable()
                    test_logger(f"smod is reachable: {smod_status}", console=False)
                    test_logger(f"check_and_disable_tx exception: {e}", console=False)
                    if not smod_status:
                        return True
            else:
                return False
        return True

    @method_decorator("node_alias")
    def is_tx_enable(self):
        status = self.ssh_manager.execute_command(f"cat /sys/class/sfp/{self.trs_sfp}/tx_disable", timeout="15 seconds")
        test_logger(f"tx_disable_status: {status}", "DEBUG")
        return not int(status.split()[0])

    @method_decorator()
    def update_sw_and_wait_for_reload(self, ims2_path=None):
        self.update_sw(ims2_path=ims2_path)

    @method_decorator("node_alias")
    def update_sw(self, ims2_path: str = None) -> None:
        test_logger(f"Starting SW Provision on {self.mrbts_id}")
        for _ in range(3):
            try:
                thread = threading.Thread(target=self.trigger_sw_provision_from_netact)
                thread.start()
            except Exception as e:
                test_logger(f'unexpected exception durin sw provision: {e}')
            for _ in range(12):
                if self.get_download_status() in ["Ongoing"]:
                    test_logger("Sw Provision request ongoing waiting for SW activation.")
                    return
                time.sleep(5)
        raise ProvisionStartFailure('Provision from NetAct did not start')

    @method_decorator()
    def trigger_sw_provision_from_netact(self):
        try:
            self.netact.provision_sw(self.netact_target_sw, self.mo_dist_name)
        except Exception:
            pass

    @method_decorator()
    def restore_all_interfaces(self):
        for _ in range(3):
            try:
                if self.check_node_availability():
                    self.toggle_port_443_access_on_smod("enable")
                    self.admin.reset_admin()
                    self.ssh_manager.execute_command(f"echo 0 > /sys/class/sfp/{self.trs_sfp}/tx_disable")
                    return
            except Exception as e:
                test_logger(f'restore_all_interfaces exception: {e}', "DEBUG")
            time.sleep(5)

    @method_decorator()
    def wait_for_sw_activation_reset(self, timeout: int) -> None:
        with time_limit(timeout):
            while self.is_smod_pingable():
                time.sleep(10)
        test_logger("The BTS reset has started")

    @method_decorator("node_alias")
    def clear_fallback_fault(self):
        if self.ssh_manager.file_exists("/ffs/run/config/fallbackCause.txt"):
            self.ssh_manager.execute_command("rm -rfv /ffs/run/config/fallbackCause.txt")
            if self.ssh_manager.is_slave_smod():
                self.ssh_manager.execute_command("rm -rfv /ffs/run/config/fallbackCause.txt", slave_smod=True)
            return True
        return False

    @method_decorator("node_alias")
    def set_sw_fallback_timer(self, value):
        try:
            verify_function_x_times(3, 10, self.perform_parameter_recommissioning, parameter='swFallbackTimer',
                                    dist_name=f"{self.mrbts_id}/MNL-1/MNLENT-1/FEATCADM-1", value=value)
        except Exception as e:
            test_logger(f"set_sw_fallback_timer exception: {e}", 'DEBUG')
            test_logger(f"Changing parameter swFallbackTimer failed", 'ERROR')
            raise

